        const option = document.createElement('option');
        option.value = value;
        option.textContent = value;
        defaultPriority.append(option);
      }
      defaultPriority.value = project.defaultTaskPriority || 'Normal';
      defaultPriority.addEventListener('change', async () => {
        const requested = defaultPriority.value;
        defaultPriority.disabled = true;
        const saved = await fetch(`/api/projects/${encodeURIComponent(id)}/default-priority`, {
          method: 'PATCH', headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ priority: requested }),
        });
        if (saved.ok) project.defaultTaskPriority = (await saved.json()).defaultTaskPriority;
        else defaultPriority.value = project.defaultTaskPriority || 'Normal';
        defaultPriority.disabled = project.archived;
      });
      const list = document.createElement('section');
      list.className = 'task-list';
      list.setAttribute('aria-label', 'Tasks');
      function drawTasks() {
        list.replaceChildren();
        const matching = tasks.filter((task) =>
          (filter.value === 'All' || (filter.value === 'Completed') === task.completed) &&
          (priorityFilter.value === 'All' || (task.priority || 'Normal') === priorityFilter.value) &&
          ((!appliedFrom && !appliedThrough) || (Boolean(task.dueDate) &&
            (!appliedFrom || task.dueDate >= appliedFrom) &&
            (!appliedThrough || task.dueDate <= appliedThrough))));
        for (const task of matching) {
          const row = document.createElement('div');
          row.className = 'task-row';
          row.dataset.testid = 'task-row';
          const checkbox = document.createElement('input');
          checkbox.type = 'checkbox';
          checkbox.checked = task.completed;
          checkbox.disabled = project.archived;
          checkbox.setAttribute('aria-label', `Complete ${task.title}`);
          const title = document.createElement('span');
          title.textContent = task.title;
          const priority = document.createElement('select');
          priority.setAttribute('aria-label', 'Task priority');
          priority.disabled = project.archived;

          priority.disabled = project.archived;
          for (const value of ['Low', 'Normal', 'High']) {
            const option = document.createElement('option');
            option.value = value;
            option.textContent = value;
            priority.append(option);
          }
          priority.value = task.priority || 'Normal';
          priority.addEventListener('change', async () => {
            priority.disabled = true;
            const saved = await fetch(`/api/projects/${encodeURIComponent(id)}/tasks/${task.id}/priority`, {
              method: 'PATCH', headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ priority: priority.value }),
            });
            if (saved.ok) task.priority = (await saved.json()).priority;
            else priority.value = task.priority || 'Normal';
            priority.disabled = project.archived;
            drawTasks();
          });
          const dueDateForm = document.createElement('form');
          dueDateForm.className = 'task-rename';
          const dueDateInput = document.createElement('input');
          dueDateInput.type = 'text';
          dueDateInput.autocomplete = 'off';
          dueDateInput.placeholder = 'YYYY-MM-DD';
          dueDateInput.value = task.dueDate || '';
          dueDateInput.setAttribute('aria-label', 'Task due date');
          dueDateInput.disabled = project.archived;
          const dueDateButton = document.createElement('button');
          dueDateButton.type = 'submit';
          dueDateButton.textContent = 'Save due date';
          dueDateButton.disabled = project.archived;
          dueDateForm.append(dueDateInput, dueDateButton);
          dueDateForm.addEventListener('submit', async (event) => {
            event.preventDefault();
            const requested = dueDateInput.value.trim();
            const saved = await fetch(`/api/projects/${encodeURIComponent(id)}/tasks/${task.id}/due-date`, {
              method: 'PATCH', headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ dueDate: requested }),
            });
            if (!saved.ok) {
              alert.textContent = (await saved.json()).error || 'Could not save due date';
              alert.hidden = false;
              return;
            }
            task.dueDate = (await saved.json()).dueDate;
            dueDateInput.value = task.dueDate || '';
            alert.hidden = true;
            drawTasks();
          });
          const renameForm = document.createElement('form');
          renameForm.className = 'task-rename';
          const renameInput = document.createElement('input');
          renameInput.type = 'text';
          renameInput.autocomplete = 'off';
          renameInput.setAttribute('aria-label', 'New task title');
          renameInput.disabled = project.archived;
          const renameButton = document.createElement('button');
          renameButton.type = 'submit';
          renameButton.textContent = 'Rename task';
          renameButton.disabled = project.archived;
          renameForm.append(renameInput, renameButton);
          renameForm.addEventListener('submit', async (event) => {
            event.preventDefault();
            const newTitle = renameInput.value.trim();
            if (!newTitle) {
              alert.textContent = 'Task title is required';
              alert.hidden = false;
              renameInput.focus();
              return;
            }
            const saved = await fetch(`/api/projects/${encodeURIComponent(id)}/tasks/${task.id}/rename`, {
              method: 'PATCH', headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ title: newTitle }),
            });
            if (!saved.ok) {
              alert.textContent = (await saved.json()).error || 'Could not rename task';
              alert.hidden = false;
              return;
            }
            task.title = (await saved.json()).title;
            alert.hidden = true;
            drawTasks();
          });
          checkbox.addEventListener('change', async () => {
            checkbox.disabled = true;
            const saved = await fetch(`/api/projects/${encodeURIComponent(id)}/tasks/${task.id}`, {
              method: 'PATCH', headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ completed: checkbox.checked }),
            });
            if (saved.ok) task.completed = checkbox.checked;
            checkbox.disabled = false;
            drawTasks();
          });
          row.append(checkbox, title, renameForm, priority, dueDateForm);
          list.append(row);
        }
      }
      filter.addEventListener('change', drawTasks);
      priorityFilter.addEventListener('change', drawTasks);
      form.addEventListener('submit', async (event) => {
        event.preventDefault();
        const title = input.value.trim();
        if (!title) {
          alert.textContent = 'Task title is required';
          alert.hidden = false;
          input.focus();
          return;
        }
        alert.hidden = true;
        const created = await fetch(`/api/projects/${encodeURIComponent(id)}/tasks`, {
          method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ title }),
        });
        if (!created.ok) {
          alert.textContent = (await created.json()).error || 'Could not create task';
          alert.hidden = false;
          return;
        }
        tasks.push(await created.json());
        input.value = '';
        drawTasks();
      });
      renameForm.addEventListener('submit', async (event) => {
        event.preventDefault();
        const name = renameInput.value.trim();
        if (!name) {
          alert.textContent = 'Project name is required';
          alert.hidden = false;
          renameInput.focus();
          return;
        }
        const saved = await fetch(`/api/projects/${encodeURIComponent(id)}`, {
          method: 'PATCH', headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ name }),
        });
        if (!saved.ok) {
          alert.textContent = (await saved.json()).error || 'Could not rename project';
          alert.hidden = false;
          return;
        }
        project.name = (await saved.json()).name;
        heading.textContent = project.name;
        renameInput.value = '';
        alert.hidden = true;
      });
      app.append(back, heading, archivedNotice, renameForm, form, alert, controls, dueRangeForm, defaultPriorityLabel, defaultPriority, list);
      drawTasks();
    }

    const match = location.pathname.match(/^\/projects\/(\d+)\/?$/);
    (match ? renderProject(match[1]) : loadProjects().then(renderList)).catch(() => {
      app.textContent = 'Unable to load Workboard. Please refresh the page.';
    });
  </script>
</body>
</html>
